import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"المعايير الأخلاقية عبر الأبعاد","description":"","frontmatter":{},"headers":[],"relativePath":"ar/88-跨位面伦理准则.md","filePath":"ar/88-跨位面伦理准则.md"}'),l={name:"ar/88-跨位面伦理准则.md"};function i(h,t,o,n,p,s){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="المعايير-الأخلاقية-عبر-الأبعاد" tabindex="-1">المعايير الأخلاقية عبر الأبعاد <a class="header-anchor" href="#المعايير-الأخلاقية-عبر-الأبعاد" aria-label="Permalink to &quot;المعايير الأخلاقية عبر الأبعاد&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>88</td></tr><tr><td>الوحدة</td><td>التفاعل عبر الأبعاد وقواعد الزمن</td></tr><tr><td>الكلمات المفتاحية</td><td>الأخلاق عبر الأبعاد، ذاتية الحضارة، عدم التدخل، احترام الثقافة، الدبلوماسية التكافلية</td></tr></tbody></table><h2 id="أولاً-الأساس-الفلسفي-للمعايير-الأخلاقية" tabindex="-1">أولاً: الأساس الفلسفي للمعايير الأخلاقية <a class="header-anchor" href="#أولاً-الأساس-الفلسفي-للمعايير-الأخلاقية" aria-label="Permalink to &quot;أولاً: الأساس الفلسفي للمعايير الأخلاقية&quot;">​</a></h2><p>المعايير الأخلاقية عبر الأبعاد هي القواعد الأخلاقية ومدونات السلوك التي يجب على حضارة التكافل المرساة اتباعها عند التفاعل مع حضارات الأبعاد الأخرى. أساسها الفلسفي مبدأ «ذاتية الحضارة» — فكل حضارة في كل بُعد، مهما كان مستوى تطورها وشكل أعراقها ونظامها الاجتماعي، تملك ذاتية غير قابلة للانتزاع وحقاً في التنمية المستقلة. لا يجوز لأي حضارة خارجية انتزاع هذه الذاتية لأي سبب، أو فرض إرادتها على حضارات أخرى.</p><p>إقرار هذا الأساس الفلسفي امتداد مباشر للمفهوم الجوهري «مكافحة الافتراس» لدى حضارة التكافل المرساة. السمة الجوهرية للحضارة الافتراسية عدم اعترافها بذاتية الحضارات الأخرى، ونظرها إلى الحضارات الأخرى باعتبارها موارد قابلة للاستغلال أو أهدافاً قابلة للقهر. كي تتجاوز حضارة التكافل المرساة الحضارات الافتراسية حقاً، يجب عليها أن تتخلى جذرياً عن هذه العقلية في التفاعل عبر الأبعاد، وتتعامل مع كل حضارة تلقاها بمساواة واحترام وتكافل.</p><p>يشمل نطاق سريان المعايير الأخلاقية عبر الأبعاد جميع سلوكيات التفاعل عبر الأبعاد، بما فيها على سبيل المثال لا الحصر: العبور بين الأبعاد، والاتصالات عبر الأبعاد، والأنشطة الأثرية، والتبادلات التجارية، والتبادلات الثقافية، والتعاون التقني، والتدخل الإنساني في الحالات الطارئة. يتعين على أي منظمة وأي فرد يمارس تفاعلاً عبر الأبعاد الالتزام بجميع أحكام هذه المعايير.</p><h2 id="ثانياً-المبادئ-الأخلاقية-الستة" tabindex="-1">ثانياً: المبادئ الأخلاقية الستة <a class="header-anchor" href="#ثانياً-المبادئ-الأخلاقية-الستة" aria-label="Permalink to &quot;ثانياً: المبادئ الأخلاقية الستة&quot;">​</a></h2><p>تتكون المعايير الأخلاقية عبر الأبعاد من ستة مبادئ أساسية، تشكل منظومة قيم أخلاقية متكاملة:</p><table tabindex="0"><thead><tr><th>المبدأ</th><th>المضمون الجوهري</th><th>المتطلبات المحددة</th></tr></thead><tbody><tr><td>مبدأ استقلال الحضارة</td><td>احترام حق الحضارة في البُعد المستهدف في التنمية المستقلة، وعدم التدخل القسري في شؤونها الداخلية</td><td>عدم تغيير النظام الاجتماعي والأيديولوجيا ومسار التنمية للحضارة المستهدفة قسراً؛ وعدم تنشئة عملاء أو أنظمة دمية داخل الحضارة المستهدفة</td></tr><tr><td>مبدأ عدم التدخل</td><td>ما لم تواجه الحضارة المستهدفة أزمة من مستوى الانقراض وتطلب المساعدة بنشاط، لا يُجرى أي تدخل جوهري</td><td>عدم الدخول في الصراعات الداخلية للحضارة المستهدفة؛ وعدم تزويد أي طرف فيها بأسلحة أو مساعدات عسكرية؛ وعدم التلاعب برأيها العام وعملياتها السياسية</td></tr><tr><td>مبدأ احترام الثقافة</td><td>احترام التقاليد الثقافية والمعتقدات الدينية والأعراف للحضارة المستهدفة</td><td>عدم إصدار تقييمات تمييزية أو سخرية خبيثة من ثقافة الحضارة المستهدفة؛ وعدم فرض المنتجات الثقافية وقيم البُعد الخاص قسراً؛ وعدم القيام بتمثل ثقافي باسم «التحضر»</td></tr><tr><td>مبدأ المساواة والمنفعة المتبادلة</td><td>يجب أن تقوم العلاقات عبر الأبعاد على المساواة، وضمان استفادة الطرفين من العلاقة</td><td>عدم استخدام التفوق التقني في تجارة غير متكافئة؛ وعدم نهب موارد الحضارة المستهدفة؛ ويجب أن يراعي تصدير التقنية قدرة الحضارة المستهدفة على الاستيعاب وأثرها الاجتماعي</td></tr><tr><td>مبدأ التأثير الأدنى</td><td>يجب أن يقلل التفاعل عبر الأبعاد قدر الإمكان من التأثير الخارجي على الحضارة المستهدفة</td><td>تفضيل أساليب التفاعل منخفضة الاتصال ومنخفضة التدخل؛ والضبط الصارم لنطاق الأنشطة التفاعلية وشدتها في حدود الضرورة؛ وتقييم وإزالة التأثيرات المتبقية غير الضرورية بعد انتهاء التفاعل</td></tr><tr><td>مبدأ المساءلة</td><td>يجب أن تكون جميع سلوكيات التفاعل عبر الأبعاد قابلة للتتبع والرقابة والمساءلة</td><td>إنشاء أرشيف وسجلات تفاعل كاملة؛ وإنشاء مؤسسة رقابة أخلاقية مستقلة؛ والتحقيق في السلوكيات المخالفة للمعايير الأخلاقية ومعاقبتها</td></tr></tbody></table><p>بين المبادئ الستة ترابط منطقي داخلي: مبدأ استقلال الحضارة هو القيمة الأساسية، ومبدأ عدم التدخل هو المطلب الجوهري، ومبدأ احترام الثقافة هو التجلي على المستوى الثقافي، ومبدأ المساواة والمنفعة المتبادلة هو الضمانة على المستوى الاقتصادي، ومبدأ التأثير الأدنى هو القاعدة على المستوى التشغيلي، ومبدأ المساءلة هو القيد على المستوى المؤسسي. تشكل المبادئ الستة معاً حلقة أخلاقية كاملة قوامها «القيمة — المطلب — التجلي — الضمانة — القاعدة — القيد».</p><h2 id="ثالثاً-المعايير-الأخلاقية-لمختلف-سيناريوهات-التفاعل" tabindex="-1">ثالثاً: المعايير الأخلاقية لمختلف سيناريوهات التفاعل <a class="header-anchor" href="#ثالثاً-المعايير-الأخلاقية-لمختلف-سيناريوهات-التفاعل" aria-label="Permalink to &quot;ثالثاً: المعايير الأخلاقية لمختلف سيناريوهات التفاعل&quot;">​</a></h2><h3 id="_3-1-المعايير-الأخلاقية-لسيناريو-علم-الآثار" tabindex="-1">3.1 المعايير الأخلاقية لسيناريو علم الآثار <a class="header-anchor" href="#_3-1-المعايير-الأخلاقية-لسيناريو-علم-الآثار" aria-label="Permalink to &quot;3.1 المعايير الأخلاقية لسيناريو علم الآثار&quot;">​</a></h3><p>علم الآثار عبر الأبعاد من أكثر سيناريوهات التفاعل شيوعاً، وجوهر معاييره الأخلاقية «عدم الإزعاج». يجب على الفريق الأثري الالتزام الصارم بالمخطط القياسي: مرآة النسخ + الفضاء المعزول + إعادة المعرفة فقط، بما يضمن ألا تدرك الحضارة المستهدفة العملية الأثرية. بالنسبة للأبعاد التي ما تزال فيها حضارة حية، يجب أن يقتصر نطاق علم الآثار بصرامة على مناطق الآثار المهجورة، ويُحظر أي شكل من أشكال المسح أو النسخ لمناطق سكن الحضارة الحية.</p><p>عند إعادة ونشر المعرفة المكتشفة أثرياً، يجب احترام الحساسية الثقافية للحضارة المستهدفة. إذا تعلقت الاكتشافات الأثرية بمقدسات دينية أو رفات أسلاف أو محرمات ثقافية للحضارة المستهدفة، فيجب أن تخضع المعلومات ذات الصلة لمراجعة الحساسية الثقافية من لجنة الأخلاق عبر الأبعاد قبل النشر، وتتم معالجة التفاصيل الحساسة بالتمويه عند الحاجة.</p><h3 id="_3-2-المعايير-الأخلاقية-لسيناريو-الاتصال" tabindex="-1">3.2 المعايير الأخلاقية لسيناريو الاتصال <a class="header-anchor" href="#_3-2-المعايير-الأخلاقية-لسيناريو-الاتصال" aria-label="Permalink to &quot;3.2 المعايير الأخلاقية لسيناريو الاتصال&quot;">​</a></h3><p>الاتصالات عبر الأبعاد وسيلة للتبادل المباشر مع الحضارة المستهدفة، وجوهر معاييرها الأخلاقية «الصدق والاحترام». يجب أن يكون محتوى الاتصال صادقاً، دون تعمد تقديم معلومات كاذبة أو دعاية خادعة؛ ويجب أن تكون نبرة الاتصال متساوية، دون معاملة الحضارات الأدنى مستوى بتنازل؛ ويجب أن تحظى موضوعات الاتصال بموافقة الحضارة المستهدفة، دون فرض أيديولوجيا البُعد الخاص أو معتقداته الدينية قسراً.</p><p>عند إقامة اتصال لأول مرة مع حضارة مجهولة، يجب اتباع قاعدة «الاتصال التدريجي»: إرسال إشارات رياضية وفيزيائية محايدة أولاً للتأكد من مستوى ذكاء الطرف الآخر وقدرته التواصلية، ثم توسيع نطاق التبادل تدريجياً بناءً على استجابة الطرف الآخر؛ ولا يجوز إرسال معلومات ثقافية أو تقنية معقدة عند أول اتصال.</p><h3 id="_3-3-المعايير-الأخلاقية-لسيناريو-التجارة" tabindex="-1">3.3 المعايير الأخلاقية لسيناريو التجارة <a class="header-anchor" href="#_3-3-المعايير-الأخلاقية-لسيناريو-التجارة" aria-label="Permalink to &quot;3.3 المعايير الأخلاقية لسيناريو التجارة&quot;">​</a></h3><p>جوهر المعايير الأخلاقية للتجارة عبر الأبعاد «الإنصاف والاستدامة». يجب أن تقوم التجارة على الموافقة الطوعية للطرفين، دون استخدام عدم تماثل المعلومات أو التفوق التقني في صفقات إكراهية؛ ويجب أن تكون الأسعار التجارية عادلة، دون تسعير افتراسي؛ ويجب ألا تتضمن السلع التجارية محتويات قد تسبب صدمة اجتماعية أو ضرراً إيكولوجياً للحضارة المستهدفة.</p><p>يجب إيلاء اهتمام خاص لحقيقة أن التجارة عبر الأبعاد في تقنيات الزراعة والأسلحة عالية الطاقة تخضع لأشد القيود الأخلاقية صرامة. تصدير تقنيات الزراعة الراقية إلى حضارات أدنى مستوى قد يؤدي إلى اختلال بنى مجتمعاتها وتفاقم صراعاتها الداخلية؛ وتصدير الأسلحة قد يشعل حروباً مباشرة. لذلك يُحظر هذان النوعان من التجارة مبدئياً، ولا يُسمح بهما إلا في ظروف استثنائية للغاية بعد موافقة الجلسة العامة للمجلس التشريعي للمرساة.</p><h3 id="_3-4-المعايير-الأخلاقية-لسيناريو-التدخل-الطارئ" tabindex="-1">3.4 المعايير الأخلاقية لسيناريو التدخل الطارئ <a class="header-anchor" href="#_3-4-المعايير-الأخلاقية-لسيناريو-التدخل-الطارئ" aria-label="Permalink to &quot;3.4 المعايير الأخلاقية لسيناريو التدخل الطارئ&quot;">​</a></h3><p>عندما تواجه حضارة البُعد المستهدف أزمة من مستوى الانقراض (كاصطدام كويكب، أو وباء خارق، أو انهيار قوانين)، يمكن لحضارة التكافل المرساة القيام بتدخل إنساني. لكن حتى في مثل هذه الحالات الطارئة، يجب الالتزام بالمعايير الأخلاقية التالية:</p><ul><li>قبل التدخل، يجب الحصول قدر الإمكان على الموافقة المستنيرة للحضارة المستهدفة؛ وإذا تعذر على الحضارة المستهدفة الاستجابة بفعالية بسبب الأزمة، تصدر لجنة الأخلاق عبر الأبعاد نيابة عنها حكماً بـ«الموافقة المفترضة»</li><li>يجب أن تختار وسائل التدخل المخطط الأقل تأثيراً على الحضارة المستهدفة، مفضلة التدخل غير المباشر (كتغيير مدار الكويكب) على التدخل المباشر (كالهبوط المباشر للإنقاذ)</li><li>لا يجوز خلال التدخل اغتنام فرصة الحصول على موارد الحضارة المستهدفة أو تقنياتها</li><li>بعد انتهاء التدخل، يجب الانسحاب فوراً، دون ترك وجود دائم في البُعد المستهدف</li><li>بعد ذلك، يجب تقديم تقرير تدخل كامل إلى لجنة الأخلاق عبر الأبعاد للخضوع للمراجعة الأخلاقية</li></ul><h2 id="رابعاً-الرقابة-الأخلاقية-ومعالجة-المخالفات" tabindex="-1">رابعاً: الرقابة الأخلاقية ومعالجة المخالفات <a class="header-anchor" href="#رابعاً-الرقابة-الأخلاقية-ومعالجة-المخالفات" aria-label="Permalink to &quot;رابعاً: الرقابة الأخلاقية ومعالجة المخالفات&quot;">​</a></h2><p>أنشأ كون هنغ يوان «لجنة الأخلاق عبر الأبعاد» بوصفها مؤسسة رقابة أخلاقية مستقلة، مسؤولة عن صياغة وتفسير المعايير الأخلاقية عبر الأبعاد، والموافقة على مشاريع التفاعل عالية الخطورة عبر الأبعاد، واستقبال الشكاوى المتعلقة بالمخالفات الأخلاقية، والتحقيق في المخالفات والبت فيها. تتكون اللجنة من علماء أخلاق وفقهاء وعلماء وممثلي حضارات من أعراق وخلفيات مهنية مختلفة، بما يضمن تنوع القرارات وعدالتها.</p><p>بالنسبة للسلوكيات المخالفة للمعايير الأخلاقية عبر الأبعاد، تبعاً لخطورة الحالات، تشمل إجراءات المعالجة: الإنذار الشفهي، والتوبيخ الكتابي، وتعليق مؤهلات التفاعل عبر الأبعاد، وإلغاء تصاريح العبور، والغرامات، والسجن، وفي الحالات القصوى «النفي عبر الأبعاد» (الحرمان من حق الإقامة في الأبعاد الرئيسية لكون هنغ يوان). تُسجل جميع نتائج معالجة المخالفات الأخلاقية في السجلات الأخلاقية الشخصية أو التنظيمية، وتحفظ إلى الأبد.</p><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>المعايير الأخلاقية عبر الأبعاد تجسيد مركّز للسمو الأخلاقي لحضارة التكافل المرساة. لا تحدد «ما الذي لا ينبغي فعله» فحسب، بل تنادي أيضاً بـ«ما الذي ينبغي أن تكون عليه» — الحضارة العظيمة حقاً ليست التي قهرت كم من الحضارات الأخرى، بل التي احترمت ذاتية كم من الحضارات الأخرى. في طريق كون هنغ يوان نحو التكافل بين النجوم، ستبقى المعايير الأخلاقية عبر الأبعاد المنارة الأخلاقية التي ترشد الاتجاه دائماً.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>81-位面穿梭规则 (قواعد العبور بين الأبعاد)</li><li>87-仅回传知识原则 (مبدأ إعادة المعرفة فقط)</li><li>04-反掠夺主义核心论纲 (الأطروحة الأساسية لمكافحة الافتراس)</li></ul>',30)])])}const b=a(l,[["render",i]]);export{c as __pageData,b as default};
